function backup(){const data=JSON.stringify({app:'history_archive_local_v1',version:1,exportedAt:new Date().toISOString(),saved:{...saved,quizActive:quiz&&!quiz.done?quiz:null},arcadeV2:(()=>{try{return JSON.parse(localStorage.getItem('history_arcade_local_v2')||'null')}catch{return null}})()},null,2);const blob=new Blob([data],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='history_archive_backup_'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('백업 파일을 저장했습니다.')}
function restore(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const d=JSON.parse(reader.result);if(d.app!=='history_archive_local_v1'||typeof d.saved!=='object')throw Error('형식 오류');saved={...defaults(),...d.saved};if(d.arcadeV2&&typeof d.arcadeV2==='object'){localStorage.setItem('history_arcade_local_v2',JSON.stringify(d.arcadeV2));window.HistoryArcade?.syncFromStorage?.()}quiz=saved.quizActive&&!saved.quizActive.done?saved.quizActive:null;write();render();toast('복원을 완료했습니다.')}catch{toast('올바른 시간의 서고 백업 파일이 아닙니다.')}};reader.readAsText(file)}
