function stopAnimation(){if(storyAnimation){cancelAnimationFrame(storyAnimation);storyAnimation=null}game=null;keys={left:false,right:false};heldPointers.clear();autoWalkTarget=null;autoInteractTarget=null}
function openChapter(i){if(!D.stories[i])return;storyEpisode=i;storyUI=null;nav('story');requestAnimationFrame(()=>{window.scrollTo({top:0,behavior:'instant'});document.querySelector('#view')?.scrollTo?.(0,0)});tone(470)}
function fitGameCanvas(canvas){if(!canvas)return;const portrait=window.matchMedia('(max-width:700px) and (orientation:portrait)').matches;GW=portrait?570:960;if(canvas.width!==GW){canvas.width=GW;canvas.height=GH}if(game)game.camera=Math.max(0,Math.min(WORLD-GW,game.player.x-GW*.23))}
function jumpStory(){if(!game||storyUI||game.player.jumps>=2)return;const p=game.player;p.slide=0;p.v=p.jumps===0?560:505;p.jump=Math.max(0,p.jump);p.jumps++;p.jumps===2&&spawnRunnerBurst(p.x,FLOOR-p.jump-65,'#f5d68e');tone(p.jumps===2?690:470,.05)}
function slideStory(){if(!game||storyUI||game.player.jump>2)return;game.player.slide=.85;tone(315,.04)}
