function runnerHazards(){const types=['crate','sign','barrier','crate','sign','barrier','crate','sign','barrier','crate','sign','crate','barrier','sign','crate'];const spots=[510,800,990,1110,1490,1800,2020,2240,2480,2800,3030,3190,3340,3510,3690];return spots.map((x,i)=>({x,kind:types[i],hit:false}))}
function runnerTokens(){const a=[];for(let x=210,i=0;x<3710;x+=89,i++){if([460,770,1310,1590].some(v=>Math.abs(v-x)<65))continue;const wave=i%6;const height=wave===2||wave===3?105:40;a.push({x,height,kind:'memory',taken:false})}a.push({x:1950,height:43,kind:'heart',taken:false});return a}
function startGame(){const canvas=$('#gameCanvas');if(!canvas)return;fitGameCanvas(canvas);const s=D.stories[storyEpisode];game={canvas,ctx:canvas.getContext('2d'),player:{x:105,jump:0,v:0,jumps:0,slide:0,step:0,hitFlash:0,face:1},camera:0,objects:[{x:1240,kind:'cinematic',idx:0,triggered:false},{x:2630,kind:'cinematic',idx:1,triggered:false},{x:3860,name:'역사 확인 관문',kind:'exit',triggered:false}],hazards:runnerHazards(),tokens:runnerTokens(),particles:[],hp:3,score:0,combo:0,maxCombo:0,collected:0,speed:278,meters:0,started:false,lastNear:null};storyUI={kind:'intro'};showStoryUI();prevFrame=performance.now();const loop=now=>{if(!game)return;const dt=Math.min(.036,(now-prevFrame)/1000||.016);prevFrame=now;updateGame(dt);drawGame(now/1000);storyAnimation=requestAnimationFrame(loop)};storyAnimation=requestAnimationFrame(loop)}
function spawnRunnerBurst(x,y,color){if(!game)return;for(let i=0;i<7;i++)game.particles.push({x,y,vx:(i-3)*34,vy:-20-(i%3)*26,life:.5,color})}
function runnerStats(){if(!game)return;const lives=$('#runnerLives'),score=$('#runnerScore'),progress=$('#runnerProgress');if(lives)lives.textContent='♥ '.repeat(game.hp)+'♡ '.repeat(3-game.hp);if(score)score.textContent=`✦ ${game.score.toLocaleString()}점${game.combo>2?' · '+game.combo+'콤보':''}`;if(progress)progress.style.width=`${Math.min(100,Math.max(0,(game.player.x-105)/(3860-105)*100)).toFixed(1)}%`;updateClueCounter()}
function updateGame(dt){if(!game)return;const g=game,p=g.player;if(storyUI?.kind==='cinematic'){g.cutsceneElapsed=(g.cutsceneElapsed||0)+dt;if(g.cutsceneElapsed>=6.2)closeStoryUI()}for(const q of g.particles){q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=95*dt;q.life-=dt}g.particles=g.particles.filter(q=>q.life>0);
if(!storyUI&&g.started){p.x=Math.min(WORLD-60,p.x+g.speed*dt);p.step+=dt*16;p.slide=Math.max(0,p.slide-dt);p.hitFlash=Math.max(0,p.hitFlash-dt);if(p.jump>0||p.v>0){p.jump+=p.v*dt;p.v-=1480*dt;if(p.jump<=0){p.jump=0;p.v=0;p.jumps=0}}g.camera=Math.max(0,Math.min(WORLD-GW,p.x-GW*.23));g.speed=278+Math.min(44,Math.floor((p.x-105)/850)*11);
for(const h of g.hazards){if(h.hit||Math.abs(h.x-p.x)>24)continue;h.hit=true;const safe=h.kind==='sign'?p.slide>.06&&p.jump<12:p.jump>(h.kind==='barrier'?77:65);if(!safe){g.hp--;g.combo=0;p.hitFlash=.8;spawnRunnerBurst(p.x,FLOOR-p.jump-50,'#ffba93');tone(185,.12);toast('장애물에 부딪혔어요! 점프·슬라이드 타이밍을 맞춰 보세요.');if(g.hp<=0){storyUI={kind:'retry'};showStoryUI();break}}else{g.score+=25;spawnRunnerBurst(h.x,FLOOR-52,'#b7e3ad')}}
if(!storyUI)for(const token of g.tokens){if(token.taken||Math.abs(token.x-p.x)>31||Math.abs(p.jump-token.height)>62)continue;token.taken=true;if(token.kind==='heart'){g.hp=Math.min(3,g.hp+1);g.score+=100;tone(650,.07)}else{g.collected++;g.combo++;g.maxCombo=Math.max(g.combo,g.maxCombo);g.score+=100+Math.min(10,g.combo)*10;spawnRunnerBurst(token.x,FLOOR-token.height,'#fbdc81');if(g.combo%6===0)tone(770,.05)}}
if(!storyUI)for(const o of g.objects){if(o.triggered||p.x<o.x-22)continue;o.triggered=true;if(o.kind==='cinematic'){const s=D.stories[storyEpisode],v=saved.storyFound[s.id]||[];if(!v.includes(o.idx)){saved.storyFound[s.id]=[...v,o.idx];write();g.score+=350}g.cutsceneElapsed=0;storyUI={kind:'cinematic',idx:o.idx};showStoryUI();tone(445,.06)}else if(o.kind==='exit'){storyUI={kind:hasAllClues()?'gate':'missed'};showStoryUI()}break}
}
runnerStats();const warn=$('#runnerWarning'),next=g.hazards.find(h=>!h.hit&&h.x>p.x);if(warn){const dist=next?next.x-p.x:9999;warn.classList.toggle('visible',!storyUI&&dist<520&&dist>0);if(!storyUI&&dist<520&&dist>0){const slide=next.kind==='sign';warn.classList.toggle('slide-warning',slide);warn.textContent=(slide?'↓ 슬라이드':'↑ 점프')+' 장애물 · '+Math.round(dist/10)*10+' 거리'}else warn.textContent=''}const prompt=$('#gamePrompt');if(prompt)prompt.textContent=storyUI?.kind==='cinematic'?'🎞️ 역사 컷신 재생 중 · 자동으로 이어집니다':storyUI?'역사 퀴즈 / 잠시 정지':g.combo>=5?`✦ ${g.combo} 콤보! 계속 달려 보세요`:'⬆ 주황 장애물 점프 · ⬇ 보라 장애물 슬라이드!'}
function fill(ctx,color,x,y,w,h){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h))}
function drawRunnerObstacle(c,h,cam,t){const x=h.x-cam,y=FLOOR;if(x< -115||x>GW+115)return;
const slide=h.kind==='sign',color=slide?'#ab64ef':'#ffae45',accent=slide?'#f4b7ff':'#ffeb83';c.save();if(h.hit)c.globalAlpha=.32;
// Ground shadow and high-contrast halo keep the hazard separate from background props.
c.shadowColor=slide?'#c96cff':'#ff6a29';c.shadowBlur=17+Math.sin(t*5)*3;
c.fillStyle=slide?'#8f47ca':'#f97b36';c.fillRect(x-51,y-3,102,6);c.shadowBlur=0;
c.fillStyle='#171827';c.strokeStyle='#10121c';c.lineWidth=5;
if(slide){
 // Hanging purple header: standing height intersects the 31-90px interval; slide clears under it.
 c.fillStyle='#3d245d';c.fillRect(x-46,y-125,92,98);c.strokeRect(x-46,y-125,92,98);
 c.fillStyle='#c57bff';c.fillRect(x-40,y-116,80,73);c.fillStyle='#43265d';c.fillRect(x-34,y-108,68,6);
 for(let i=0;i<5;i++){c.fillStyle=i%2?'#331a49':'#e6c0ff';c.fillRect(x-38+i*16,y-57,16,14)}
 c.fillStyle='#ffffff';c.textAlign='center';c.font='900 21px sans-serif';c.fillText('↓',x,y-77);c.font='900 15px sans-serif';c.fillText('슬라이드',x,y-92);c.fillStyle='#222035';c.fillRect(x-48,y-3,96,5);
}else{
 const tall=h.kind==='barrier',w=tall?66:66,hh=tall?79:58;
 c.fillStyle='#201f28';c.fillRect(x-w/2-3,y-hh-3,w+6,hh+3);
 c.fillStyle=color;c.fillRect(x-w/2,y-hh,w,hh);
 c.strokeStyle='#1c1820';c.lineWidth=5;c.strokeRect(x-w/2,y-hh,w,hh);
 c.fillStyle='#fef1a0';for(let k=-w/2+4;k<w/2-3;k+=20){c.beginPath();c.moveTo(x+k,y-7);c.lineTo(x+k+12,y-hh+8);c.lineTo(x+k+19,y-hh+8);c.lineTo(x+k+6,y-7);c.fill()}
 c.fillStyle='#2b2630';c.fillRect(x-26,y-hh+8,52,33);c.fillStyle='#fff9dc';c.textAlign='center';c.font='900 18px sans-serif';c.fillText('↑ 점프',x,y-hh+30);
 if(tall){c.fillStyle='#f1c347';c.fillRect(x-32,y-11,64,7)}
}
if(!h.hit){c.fillStyle=accent;c.strokeStyle='#242138';c.lineWidth=4;c.beginPath();c.roundRect(x-37,y-(slide?167:111),74,27,8);c.fill();c.stroke();c.fillStyle='#261b25';c.font='900 14px sans-serif';c.textAlign='center';c.fillText(slide?'SLIDE ↓':'JUMP ↑',x,y-(slide?148:92));}
c.restore()}
function drawRunnerToken(c,token,cam,t){if(token.taken)return;const x=token.x-cam,y=FLOOR-token.height+Math.sin(t*6+token.x)*5;if(x< -32||x>GW+32)return;c.save();c.translate(x,y);if(token.kind==='heart'){c.fillStyle='#eb8b83';c.font='bold 26px sans-serif';c.textAlign='center';c.fillText('♥',0,5)}else{c.rotate(Math.sin(t*3)*.18);fill(c,'#8b6847',-12,-14,24,28);fill(c,'#f4d18a',-10,-12,20,24);fill(c,'#fff2c8',-4,-8,8,13);fill(c,'#ba915a',-10,-12,20,3)}c.restore()}
